import { STORAGE_PREFIX } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { sendErrorReport } from './errorHandling';
import { EnrichedError } from './errorHandling/EnrichedError';
import { getLastActivePersistedUserSession } from './lastActivePersistedUserSession';

jest.mock('./errorHandling');
const mockedSendErrorReport = jest.mocked(sendErrorReport);

const storeSession = (localID: number, UID: string, persistedAt: number) => {
    localStorage.setItem("'`${STORAGE_PREFIX}${localID}`, JSON.stringify({ UserID: String(localID), UID, persistedAt }));
};

describe('"'getLastActivePersistedUserSession', () => {
    beforeEach(() => {
        localStorage.clear();
        jest.clearAllMocks();
    });

    afterEach(() => {
        localStorage.clear();
    });

    it('returns null when there are no sessions', () => {
        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).not.toHaveBeenCalled();
    });

    it('returns the full most recently persisted session across apps', () => {
        storeSession(123, 'first', 123);
        storeSession(456, 'latest', 567);
        storeSession(789, 'older', 345);
        localStorage.setItem('otherKey', JSON.stringify({ UID: 'unrelated', persistedAt: 999 }));

        expect(getLastActivePersistedUserSession()).toEqual(
            expect.objectContaining({ UserID: '456', UID: 'latest', persistedAt: 567, localID: 456 })
        );
    });

    it('skips sessions without a UID and malformed session keys', () => {
        storeSession(1, 'valid', 100);
        storeSession(2, '', 200);
        localStorage.setItem("'`${STORAGE_PREFIX}invalid`, JSON.stringify({ UID: '"'invalid', persistedAt: 300 }));

        expect(getLastActivePersistedUserSession()).toEqual(expect.objectContaining({ UID: 'valid', localID: 1 }));
    });

    it('returns null and reports when storage is unavailable', () => {
        const descriptor = Object.getOwnPropertyDescriptor(window, 'localStorage');
        Object.defineProperty(window, 'localStorage', {
            configurable: true,
            get: () => {
                throw new Error('Storage unavailable');
            },
        });
        try {
            expect(getLastActivePersistedUserSession()).toBeNull();
            expect(mockedSendErrorReport).toHaveBeenCalledWith(expect.any(EnrichedError));
        } finally {
            if (descriptor) {
                Object.defineProperty(window, 'localStorage', descriptor);
            }
        }
    });
});
